                        copy[index].noOfBagsInput = v;

                        // AUTO CALCULATE ISSUE QTY
                        const bags = Number(v || 0);
                        const packingSize = Number(item.packingSize || 0);

                        copy[index].issueQty = String(bags * packingSize);

